<?php
use App\Models\{Customer,Equipment,Site};use App\Support\CurrentCompany;use Illuminate\Support\Facades\{DB,Gate};use Illuminate\Validation\Rule;use Livewire\Attributes\Title;use Livewire\Component;
new #[Title('Create Customer')] class extends Component {public int $step=1;public ?int $company_id=null;public string $name='';public ?string $trading_name=null;public string $account_number='';public ?int $home_site_id=null;public array $siteIds=[];public array $equipmentIds=[];public function mount(CurrentCompany $current):void{$this->company_id=$current->id(auth()->user());}public function next():void{if($this->step===1)$this->validate($this->rules());if($this->step===2&&!$this->home_site_id){$this->addError('home_site_id','Choose a head office address.');return;}$this->step=min(3,$this->step+1);}public function back():void{$this->step=max(1,$this->step-1);}private function rules():array{return ['name'=>['required','max:255'],'trading_name'=>['nullable','max:255'],'account_number'=>['required','max:255',Rule::unique('customers')],'company_id'=>['required','exists:companies,id']];}public function save():mixed{Gate::authorize('crm.customer.create');$data=$this->validate($this->rules()+['home_site_id'=>['required','exists:sites,id'],'siteIds'=>['array'],'siteIds.*'=>['exists:sites,id'],'equipmentIds'=>['array'],'equipmentIds.*'=>[Rule::exists('equipment','id')->where('company_id',$this->company_id)]]);DB::transaction(function()use($data){$customer=Customer::create(collect($data)->only(['name','trading_name','account_number','company_id','home_site_id'])->all());$customer->sites()->sync(array_values(array_unique([...$data['siteIds'],$data['home_site_id']])));$customer->equipment()->sync($data['equipmentIds']);});return $this->redirectRoute('crm.customers.index',navigate:true);}public function with():array{return ['sites'=>Site::orderBy('name')->get(),'equipment'=>Equipment::where('company_id',$this->company_id)->with('equipmentModel.make')->orderBy('stock_number')->get()];}};?>
<section class="w-full p-6"><flux:heading size="xl">Create Customer</flux:heading><x-pages::shared.layout contentclass="max-w-5xl"><div class="mb-6 grid grid-cols-3 gap-3">@foreach([1=>'Basic details',2=>'Addresses',3=>'Equipment'] as $n=>$label)<div class="rounded border p-3 {{ $step===$n?'border-blue-500 bg-blue-50':'' }}">Step {{ $n }}<br><strong>{{ $label }}</strong></div>@endforeach</div><form wire:submit="save" class="space-y-5">@if($step===1)<flux:card class="grid gap-5 md:grid-cols-2"><flux:input wire:model="name" label="Name"/><flux:input wire:model="trading_name" label="Trading name"/><flux:input wire:model="account_number" label="Account number"/></flux:card>@elseif($step===2)<div class="grid gap-5 md:grid-cols-2"><flux:card><flux:select wire:model="home_site_id" variant="combobox" searchable label="Head office"><flux:select.option value="">Choose address</flux:select.option>@foreach($sites as $site)<flux:select.option :value="$site->id">{{ $site->name }} — {{ $site->formattedAddress() }}</flux:select.option>@endforeach</flux:select><flux:error name="home_site_id"/></flux:card><flux:card><flux:pillbox wire:model="siteIds" multiple searchable label="Depots">@foreach($sites as $site)<flux:pillbox.option :value="$site->id">{{ $site->name }} — {{ $site->postcode }}</flux:pillbox.option>@endforeach</flux:pillbox></flux:card></div>@else<flux:card><flux:pillbox wire:model="equipmentIds" multiple searchable label="Assign equipment">@foreach($equipment as $item)<flux:pillbox.option :value="$item->id">{{ $item->stock_number }} — {{ $item->equipmentModel->make->name }} {{ $item->equipmentModel->name }}</flux:pillbox.option>@endforeach<flux:pillbox.option.create modal="new-customer-equipment" min-length="3">Add new equipment</flux:pillbox.option.create></flux:pillbox></flux:card>@endif<div class="flex justify-between border-t pt-4"><div>@if($step>1)<flux:button type="button" wire:click="back">Back</flux:button>@endif</div>@if($step<3)<flux:button type="button" variant="primary" wire:click="next">Next</flux:button>@else<flux:button type="submit" variant="primary">Save customer</flux:button>@endif</div></form><flux:modal name="new-customer-equipment" class="md:w-96"><div class="space-y-4"><flux:heading>Add equipment</flux:heading><flux:text>Create the equipment record in Stock, then return here to assign it.</flux:text><flux:button :href="route('stock.equipment.create')" target="_blank" variant="primary">Open equipment creation</flux:button></div></flux:modal></x-pages::shared.layout></section>
